// 11. End card, its own composition (the title is a horizontal lockup; this one is stacked): on the
// downbeat the mark's box springs in and its chain draws on joint by joint, as the hand did in the
// opening; the wordmark rises under it, then the box line. The music's last hit sends a specular sweep
// across mark and wordmark. Credits: the music is machine-generated by MiniMax-Music3 on this box
// (its licence asks for the credit), footage from Pexels and Pixabay. Fade to black on the tail.
// Technique: stacked lockup with draw-on, tracking-in type, a light sweep on the last hit.
import { R } from '../main.js'
import { CHAIN, drawMark } from '../lib/logo.js'
import { line, rise } from '../lib/type.js'
import { clamp, inOutCubic, mix, outCubic, outExpo, prog, spring } from '../lib/ease.js'

const K = 13 // px per logo unit: a 312 px mark
const MCX = 960, MCY = 330

export default function endcard(T) {
  const s = { id: 'endcard', z: 11 }
  let fx, lock, word, sweep, tag, fine
  const b28 = T.bar(28), b29 = T.bar(29)
  const beat = T.beat
  s.build = (root) => {
    root.style.background = '#040506'
    lock = R.el('div', 'abs', root)
    lock.style.cssText = 'inset:0;transform-origin:50% 45%'
    fx = R.canvas(lock)
    const wbox = R.el('div', 'abs', lock)
    wbox.style.cssText = 'left:0;right:0;top:530px;display:flex;justify-content:center'
    word = line(wbox, ['tacit'], { size: 250, style: 'letter-spacing:-0.035em' })
    sweep = R.el('div', 'abs', lock, 'tacit')
    sweep.style.cssText = 'left:0;right:0;top:530px;text-align:center;font-size:250px;font-weight:600;letter-spacing:-0.035em;line-height:0.92;' +
      'color:transparent;-webkit-background-clip:text;background-clip:text;' +
      'background-image:linear-gradient(105deg, rgba(255,255,255,0) 42%, rgba(220,250,255,0.95) 50%, rgba(255,255,255,0) 58%);background-size:300% 100%;opacity:0'
    tag = R.el('div', 'mono abs', root, 'Nine models · four Tenstorrent chips · one box')
    tag.style.cssText += ';left:0;right:0;text-align:center;top:850px;font-size:34px;color:#c9ced5;white-space:nowrap'
    fine = R.el('div', 'abs', root,
      'Music: MiniMax-Music3, machine-generated on chip 1 of this box &nbsp;·&nbsp; Footage: Anastasia Shuraeva, Pexels; ' +
      'AI-made comparison clip: flutie8211, Pixabay')
    fine.style.cssText = 'left:0;right:0;bottom:56px;text-align:center;font-family:"Geist Mono",monospace;font-size:19px;letter-spacing:0.02em;color:#8a919b'
  }
  s.render = (t) => {
    fx.clear()
    const g = fx.g
    // On the downbeat: box springs in, the chain draws on base to tip, joint by joint.
    const box = spring(t, b28, { zeta: 0.55, omega: 14 })
    const pts = CHAIN.map(([x, y]) => [MCX + (x - 12) * K, MCY + (y - 12) * K])
    const grow = prog(t, b28 + 0.08, 0.55, outCubic) * 3 // 0..3 bones
    const drawn = [pts[0]]
    for (let i = 1; i <= 3; i++) {
      const e = clamp(grow - (i - 1))
      if (e <= 0) break
      const [ax, ay] = pts[i - 1], [bx, by] = pts[i]
      drawn.push([mix(ax, bx, e), mix(ay, by, e)])
    }
    while (drawn.length < 4) drawn.push(drawn[drawn.length - 1])
    const glint = t >= b29 ? Math.exp(-(t - b29) * 2.2) : 0
    const ring = spring(t, b28 + 0.7, { zeta: 0.5, omega: 12 })
    if (t >= b28) drawMark(g, MCX, MCY, K, { pts: drawn, box: Math.max(0, box), ring: Math.max(0, ring) + glint * 0.8, glow: 1.1 + glint * 3 })
    // Wordmark rises a beat later; the box line tracks in after it.
    rise(word.words[0], prog(t, b28 + beat, 0.7, outExpo))
    const kt = prog(t, b28 + 2 * beat, 1.1, outExpo)
    tag.style.opacity = String(kt)
    tag.style.letterSpacing = `${mix(0.5, 0.22, kt)}em`
    // The last hit: a specular sweep across the wordmark (and the mark's glow above).
    const sw = prog(t, b29, 0.8, inOutCubic)
    sweep.style.opacity = sw > 0 && sw < 1 ? '1' : '0'
    sweep.style.backgroundPosition = `${mix(100, -50, sw)}% 0`
    fine.style.opacity = String(prog(t, b29 + 0.6, 0.9, inOutCubic))
    // A slow push so the hold never sits still; fade to black with the music's tail.
    lock.style.transform = `scale(${mix(1, 1.045, prog(t, b28, s.end - b28, (x) => x))})`
    const end = prog(t, s.end - 1.4, 1.4, inOutCubic)
    s.layer.style.opacity = String(1 - end)
  }
  return s
}
